#!/bin/sh

# The client can't be built from a checkout: its WorldMap/ and ZoneMasks/ art
# is generated by upstream CI (not committed) and Ace3 is fetched at package
# time. Install the prebuilt client release for the newest `v*` tag at or
# before the checked-out commit instead.

set -e

repo="Sectimus/HighFidelityWorldMap"
tag=$(git -C "$srcdir" describe --tags --abbrev=0 --match 'v*' HEAD)

workdir=$(mktemp -d)
trap 'rm -rf "$workdir"' EXIT
gh release download "$tag" -R "$repo" -p 'hfwm-forever-client-*.zip' -D "$workdir"
unzip -q "$workdir"/hfwm-forever-client-*.zip -d "$pkgdir"
